(() => {
const cards=[...document.querySelectorAll('.crew-card')],crew=document.querySelector('.crew'),auto=document.querySelector('.crew-auto');let selected=5,visible=false,paused=false,hover=false,lastChange=Date.now();
const bios={
'艾丝妲':['黑塔空间站','黑塔空间站的站长，兼具天文研究的热情与协调事务的从容。她将望远镜投向星空，也为这座空间站维系日常的秩序。'],
'黑塔':['黑塔空间站','天才俱乐部成员，黑塔空间站的真正主人。眼前的人偶只是她与世界交谈的方式，宇宙中值得研究的未知，才是她的兴趣所在。'],
'布洛妮娅':['贝洛伯格','贝洛伯格的年轻守护者。从熟悉的秩序走向真实的城市，在责任与选择之间，为地上和地下的人们寻找共同的未来。'],
'希儿':['贝洛伯格 · 地火','成长于贝洛伯格下层区的地火成员。行动利落，直面不公，在漫长的寒夜里，为身边的人守住一线光。'],
'景元':['仙舟「罗浮」','统率罗浮云骑军的神策将军。看似悠然，落子却深思熟虑；在漫长岁月中，始终守护着仙舟的安宁。'],
'三月七':['星穹列车','从恒冰中苏醒的少女，随星穹列车踏上旅途。用六相冰守护同伴，也用相机珍藏每一次相遇。在寻回过去之前，先把今天拍得闪闪发亮。'],
'流萤':['星核猎手','身着装甲「萨姆」的星核猎手。战斗之外，她也珍惜那些平凡而真实的瞬间，努力寻找属于自己的生活与选择。'],
'知更鸟':['匹诺康尼 · 天环族','生于匹诺康尼的天环族歌者。将心声融入歌唱，让不同的生命在旋律中相遇，也希望歌声能够抵达人们真实的心。'],
'黄泉':['自称「巡海游侠」的旅人','佩着长刀的沉默旅人，独行于遥远的星海。她循着记忆前行，在美梦与现实交错的地方，留下令人难忘的身影。'],
'停云':['仙舟「罗浮」 · 鸣火商团','罗浮鸣火商团的接渡使。笑语温和、善于交际，在往来的商旅与星槎之间，为初来仙舟的旅人引路。'],
'杰帕德':['贝洛伯格 · 银鬃铁卫','银鬃铁卫戍卫官，朗道家族的一员。沉稳而坚定，以盾牌和誓言守护贝洛伯格，让风雪中的城市继续迎来明天。']};
const reduce=()=>document.body.classList.contains('motion-off');
function select(index,manual=false){selected=(index+cards.length)%cards.length;lastChange=Date.now();cards.forEach((card,i)=>{let d=i-selected;if(d>5)d-=cards.length;if(d< -5)d+=cards.length;const a=Math.abs(d);card.setAttribute('aria-pressed',String(i===selected));card.style.zIndex=String(20-a);const target={xPercent:-50,x:d*innerWidth*.041,y:a*13,scale:1-a*.065,rotationY:d*-2,duration:reduce()?0:.8,ease:'power3.inOut',overwrite:true};if(window.gsap)gsap.to(card,target);else card.style.transform=`translateX(calc(-50% + ${d*4.1}vw)) translateY(${a*13}px) scale(${1-a*.065})`;});const c=cards[selected],bio=bios[c.dataset.name];document.querySelector('.crew-selection').setAttribute('aria-live',manual?'polite':'off');document.querySelector('.crew-selection strong').textContent=c.dataset.name;document.querySelector('.crew-selection>span').textContent=c.dataset.en;document.querySelector('.crew-selection small').textContent=c.dataset.path;document.querySelector('.crew-count').textContent=String(selected+1).padStart(2,'0')+' / 11';const details=document.querySelector('.crew-details');details.querySelector('h3').firstChild.textContent=c.dataset.name+' ';details.querySelector('h3 small').textContent=c.dataset.en;details.querySelector('.crew-detail-meta').textContent=bio[0]+' / '+c.dataset.path;details.querySelector('p').textContent=bio[1];if(!reduce()&&window.gsap)gsap.fromTo(details,{opacity:.25,y:8},{opacity:1,y:0,duration:.45,overwrite:true});}
cards.forEach((card,i)=>{card.addEventListener('click',()=>select(i,true));card.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();select(selected+(e.key==='ArrowRight'?1:-1),true);cards[selected].focus({preventScroll:true});}});});document.querySelectorAll('[data-crew-step]').forEach(b=>b.addEventListener('click',()=>select(selected+Number(b.dataset.crewStep),true)));auto.addEventListener('click',()=>{paused=!paused;auto.setAttribute('aria-pressed',String(!paused));auto.setAttribute('aria-label',paused?'继续自动轮换':'暂停自动轮换');auto.textContent=paused?'▶':'Ⅱ';lastChange=Date.now();});document.querySelectorAll('.crew-deck,.crew-details').forEach(el=>{el.addEventListener('pointerenter',()=>hover=true);el.addEventListener('pointerleave',()=>{hover=false;lastChange=Date.now();});});new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;lastChange=Date.now();},{threshold:.45}).observe(crew);setInterval(()=>{if(visible&&!paused&&!hover&&!document.hidden&&!document.body.classList.contains('scan-open')&&!reduce()&&!crew.querySelector(':focus-visible')&&Date.now()-lastChange>5000)select(selected+1);},500);let timer;addEventListener('resize',()=>{clearTimeout(timer);timer=setTimeout(()=>select(selected),150);});
})();

